ESC={'\0':'0','\x07':'a','\x08':'b','\x09':'t','\x0A':'n','\x0B':'v','\x0C':'f',
     '\x0D':'r','\x1B':'e','"':'"','\\':'\\','\x85':'N','\xA0':'_',' ':'L',' ':'P'}
TRIGGER=set('"\\\x85  ﻿')
BEST_WIDTH=80
def needs_escape(ch):
    return ch in TRIGGER or not ('\x20'<=ch<='\x7E')
def write_dq(text, column, indent, split=True):
    """Returns (emitted_string, new_column). column = column BEFORE the opening quote."""
    out=[]
    out.append('"'); column+=1
    start=end=0
    n=len(text)
    while end<=n:
        ch=text[end] if end<n else None
        if ch is None or needs_escape(ch):
            if start<end:
                d=text[start:end]; column+=len(d); out.append(d); start=end
            if ch is not None:
                if ch in ESC: d='\\'+ESC[ch]
                elif ch<='\xFF': d='\\x%02X'%ord(ch)
                elif ch<='￿': d='\\u%04X'%ord(ch)
                else: d='\\U%08X'%ord(ch)
                column+=len(d); out.append(d); start=end+1
        if 0<end<n-1 and (ch==' ' or start>=end) and column+(end-start)>BEST_WIDTH and split:
            d=text[start:end]+'\\'
            if start<end: start=end
            column+=len(d); out.append(d)
            out.append('\n'+' '*indent); column=indent          # write_indent
            if text[start]==' ':
                out.append('\\'); column+=1
        end+=1
    out.append('"'); column+=1
    return ''.join(out), column
